import { events } from '../../lib/parcel-client.js';

export function createLiveOrders(view, scope) {
  let active = false;
  let generation = 0;
  const displayed = new Map();
  const subscriptions = [];

  function releaseSubscriptions() {
    for (const subscription of subscriptions.splice(0)) subscription.close();
  }

  function render() {
    const rows = [...displayed.values()]
      .filter(order => !order.archived)
      .sort((left, right) => right.updatedAt - left.updatedAt);
    view.render(rows);
    view.setCount(rows.length);
  }

  function applyOrder(order, expectedGeneration) {
    if (!active || generation !== expectedGeneration) return;
    if (!order || !order.id) return;
    displayed.set(order.id, { ...order });
    render();
  }

  function removeOrder(id, expectedGeneration) {
    if (!active || generation !== expectedGeneration) return;
    displayed.delete(id);
    render();
  }

  function start(initialOrders = []) {
    if (active) return;
    active = true;
    generation += 1;
    const currentGeneration = generation;
    displayed.clear();
    for (const order of initialOrders) displayed.set(order.id, { ...order });
    try {
      subscriptions.push(events.subscribe(scope, 'order:changed', order => {
        applyOrder(order, currentGeneration);
      }));
      subscriptions.push(events.subscribe(scope, 'order:removed', id => {
        removeOrder(id, currentGeneration);
      }));
      render();
    } catch (error) {
      active = false;
      releaseSubscriptions();
      throw error;
    }
  }

  function stop() {
    if (!active) return;
    active = false;
    generation += 1;
    releaseSubscriptions();
    displayed.clear();
    view.setCount(0);
  }

  return { start, stop, isActive: () => active };
}

