import { payments } from '../../lib/parcel-client.js';

function validatePayment(payment) {
  if (!payment.id || !payment.customerId) throw new TypeError('Missing payment identity');
  if (!Number.isInteger(payment.amountCents) || payment.amountCents <= 0) {
    throw new TypeError('Invalid payment amount');
  }
  if (!Array.isArray(payment.lines)) throw new TypeError('Missing payment lines');
}

function retryable(error) {
  return error && error.retryable === true;
}

function deepFreeze(value) {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    for (const child of Object.values(value)) deepFreeze(child);
    Object.freeze(value);
  }
  return value;
}

export async function reconcilePayment(payment, observer, maxAttempts = 3) {
  validatePayment(payment);
  if (!Number.isInteger(maxAttempts) || maxAttempts < 1 || maxAttempts > 5) {
    throw new RangeError('Invalid retry limit');
  }
  const request = deepFreeze(structuredClone({
    paymentId: payment.id,
    customerId: payment.customerId,
    amountCents: payment.amountCents,
    lines: payment.lines,
    metadata: payment.metadata,
  }));
  const paymentId = request.paymentId;
  const idempotencyKey = 'payment:' + paymentId;
  let lastError;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    await observer.attempting({ paymentId, attempt });
    try {
      const receipt = await payments.submit(request, { idempotencyKey });
      await observer.succeeded({ paymentId, receiptId: receipt.id, attempt });
      return { paymentId, receiptId: receipt.id, attempts: attempt };
    } catch (error) {
      lastError = error;
      await observer.failed({ paymentId, attempt, retryable: retryable(error) });
      if (!retryable(error) || attempt === maxAttempts) throw error;
    }
  }
  throw lastError;
}

