import { billing } from '../../lib/parcel-client.js';

function validateInvoice(invoice) {
  if (!invoice || !invoice.id) throw new TypeError('Invoice was not found');
  if (!Number.isInteger(invoice.totalCents) || invoice.totalCents <= 0) {
    throw new TypeError('Invoice total is invalid');
  }
  if (invoice.status === 'cancelled') throw new Error('Invoice is cancelled');
}

function receiptSummary(invoice, receipt) {
  return {
    invoiceId: invoice.id,
    customerId: invoice.customerId,
    receiptId: receipt.id,
    totalCents: invoice.totalCents,
    status: 'settled',
  };
}

export async function settleInvoice(invoiceId) {
  if (typeof invoiceId !== 'string' || !invoiceId.trim()) {
    throw new TypeError('Invoice ID is required');
  }
  const invoice = await billing.lookup(invoiceId);
  validateInvoice(invoice);
  const authorization = await billing.authorize(invoice);
  let receipt;
  try {
    receipt = await billing.capture(authorization);
  } catch (captureError) {
    try {
      await billing.void(authorization.id);
    } catch {
      // The original capture failure remains the public error.
    }
    throw captureError;
  }
  return receiptSummary(invoice, receipt);
}

